# owner: platform
"""Plain text absence notices for parents."""


def absence_notice(student, marks):
    """Build a short notice listing the days the student was absent."""
    marks = list(marks)
    # Marks for another student would make the notice wrong, so refuse them.
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id} does not belong to {student.student_id}")
    dates = sorted(mark.day for mark in marks if mark.status == "absent")
    if not dates:
        raise ValueError(f"no absences for {student.student_id}")
    name = f"{student.first_name} {student.last_name}"
    lines = [f"{name} missed {len(dates)} day(s) of school:"]
    # One line per missed date, oldest first.
    for missed in dates:
        lines.append(f"- {missed.isoformat()}")
    return "\n".join(lines)
